function StealthSystem.prototype.markRec(self, index)
    do
        local i = 0
        while i < #self.marks do
            if self.marks[i + 1].enemyIndex == index then
                return self.marks[i + 1]
            end
            i = i + 1
        end
    end
    if #self.marks >= 24 or self.root == nil then
        return nil
    end
    local lb = Label("sarasa-mono-sc-regular", 22)
    if lb == nil then
        return nil
    end
    lb:addTo(self.root)
    local rec = {enemyIndex = index, lb = lb, shown = false}
    self.marks:push(rec)
    return rec
end
function StealthSystem.prototype.markSpriteRec(self, index)
    do
        local i = 0
        while i < #self.spriteMarks do
            if self.spriteMarks[i + 1].enemyIndex == index then
                return self.spriteMarks[i + 1]
            end
            i = i + 1
        end
    end
    if #self.spriteMarks >= 24 or self.root == nil then
        return nil
    end
    local qTex = self.markTexQ
    local aTex = self.markTexA
    if qTex == nil or aTex == nil then
        return nil
    end
    local q = Sprite(qTex)
    local a = Sprite(aTex)
    if q == nil or a == nil then
        return nil
    end
    q:addTo(self.root)
    a:addTo(self.root)
    q.anchor = Vec2(0.5, 0.5)
    a.anchor = Vec2(0.5, 0.5)
    q.filter = "Point"
    a.filter = "Point"
    q.visible = false
    a.visible = false
    local rec = {
        enemyIndex = index,
        q = q,
        a = a,
        qScale = qTex.height > 0 and MARK_H / qTex.height or 1,
        aScale = aTex.height > 0 and MARK_H / aTex.height or 1,
        shown = false
    }
    self.spriteMarks:push(rec)
    return rec
end
function StealthSystem.prototype.showSpriteMark(self, rec, want, info, r)
    local sp = want == 2 and rec.a or rec.q
    local other = want == 2 and rec.q or rec.a
    other.visible = false
    local topY = info.y + info.h / 2
    local rise = MARK_RISE
    local opacity = 1
    local scale = want == 2 and rec.aScale or rec.qScale
    if want == 2 then
        local age = MARK_LIFE - r.markT
        local pop = Math:min(1, age / 0.15)
        scale = scale * (0.7 + 0.3 * pop)
        rise = rise + (1 - pop) * 10
        opacity = Math:min(1, r.markT / MARK_FADE)
    end
    sp.position = Vec2(info.x, topY + rise)
    sp.scaleX = scale
    sp.scaleY = scale
    sp.opacity = opacity
    sp.visible = true
    rec.shown = true
end
function StealthSystem.prototype.hideStaleMarks(self)
    do
        local i = 0
        while i < #self.spriteMarks do
            local rec = self.spriteMarks[i + 1]
            if rec.shown then
                rec.shown = false
            else
                rec.q.visible = false
                rec.a.visible = false
            end
            i = i + 1
        end
    end
    do
        local i = 0
        while i < #self.marks do
            local rec = self.marks[i + 1]
            if rec.shown then
                rec.shown = false
            else
                rec.lb.visible = false
            end
            i = i + 1
        end
    end
end
function StealthSystem.prototype.hideAllMarks(self)
